const i=[{id:"gastritis-ulcer-001",topicId:"gastritis-ulcer",question:"Какие проявления относятся к общим симптомам заболеваний ЖКТ?",options:["Боли в животе, изжога, отрыжка, тошнота, рвота, расстройства стула","Одышка, кашель и свистящие хрипы","Головная боль в затылке и шум в ушах","Судороги в ногах и вечерние отёки"],correctIndex:0,explanation:"Общие симптомы заболеваний ЖКТ включают боли в животе, изжогу, отрыжку, тошноту, рвоту, расстройства стула, вздутие, метеоризм и снижение аппетита.",difficulty:"easy",tags:["симптомы","общие сведения"]},{id:"gastritis-ulcer-002",topicId:"gastritis-ulcer",question:"Какое изменение языка часто сопровождает заболевания ЖКТ?",options:["Ярко-красная окраска","Белый налёт","Полное отсутствие сосочков","Синюшность кончика языка"],correctIndex:1,explanation:"Признаки заболеваний ЖКТ часто сопровождаются белым налётом на языке.",difficulty:"medium",tags:["симптомы","общие сведения"]},{id:"gastritis-ulcer-003",topicId:"gastritis-ulcer",question:"Какие общие проявления сопровождают симптомы заболеваний ЖКТ?",options:["Повышение артериального давления и тахикардия","Кожная сыпь и зуд","Общая слабость, неприятный запах изо рта и быстрое снижение веса","Боли в суставах и утренняя скованность"],correctIndex:2,explanation:"Симптомы заболеваний ЖКТ сопровождаются общей слабостью, неприятным запахом изо рта, белым налётом на языке и быстрым снижением веса.",difficulty:"medium",tags:["симптомы","общие сведения"]},{id:"gastritis-ulcer-004",topicId:"gastritis-ulcer",question:"Какие заболевания относятся к самым распространённым воспалительным заболеваниям ЖКТ?",options:["Холецистит, панкреатит и гепатит","Аппендицит, дивертикулит и полипоз","Цирроз, гепатостеатоз и портальная гипертензия","Эзофагит, гастрит, энтерит, колит и гастроэнтероколит"],correctIndex:3,explanation:"Самые распространённые воспалительные заболевания ЖКТ: эзофагит, гастрит, энтерит, колит и гастроэнтероколит.",difficulty:"medium",tags:["классификация","общие сведения"]},{id:"gastritis-ulcer-005",topicId:"gastritis-ulcer",question:"Воспаление слизистой какого органа называется эзофагитом?",options:["Пищевода","Желудка","Тонкой кишки","Толстой кишки"],correctIndex:0,explanation:"Эзофагит — это воспаление слизистой пищевода.",difficulty:"easy",tags:["эзофагит","терминология"]},{id:"gastritis-ulcer-006",topicId:"gastritis-ulcer",question:"Что чаще всего вызывает эзофагит?",options:["Аутоиммунные процессы","Кислотный рефлюкс, инфекции или лекарства","Наследственные дефекты пищевода","Переохлаждение"],correctIndex:1,explanation:"Эзофагит чаще всего вызывается кислотным рефлюксом, инфекциями или лекарствами.",difficulty:"medium",tags:["эзофагит","этиология"]},{id:"gastritis-ulcer-007",topicId:"gastritis-ulcer",question:"Какие симптомы характерны для эзофагита?",options:["Диарея с кровью и вздутие живота","Боли в левом нижнем квадранте живота","Изжога, боль за грудиной и затруднённое глотание","Ночные судороги и отёки"],correctIndex:2,explanation:"Симптомы эзофагита включают изжогу, боль за грудиной и затруднённое глотание.",difficulty:"medium",tags:["эзофагит","симптомы"]},{id:"gastritis-ulcer-008",topicId:"gastritis-ulcer",question:"Воспаление слизистой какого органа представляет собой гастрит?",options:["Пищевода","Тонкой кишки","Толстой кишки","Желудка"],correctIndex:3,explanation:"Гастрит — воспаление слизистой желудка.",difficulty:"easy",tags:["гастрит","терминология"]},{id:"gastritis-ulcer-009",topicId:"gastritis-ulcer",question:"Какая бактерия является одной из основных причин гастрита?",options:["Helicobacter pylori","Escherichia coli","Mycobacterium tuberculosis","Candida albicans"],correctIndex:0,explanation:"Гастрит вызывается инфекцией Helicobacter pylori, а также НПВС, алкоголем, стрессом и неправильным питанием.",difficulty:"medium",tags:["гастрит","этиология"]},{id:"gastritis-ulcer-010",topicId:"gastritis-ulcer",question:"Какая группа лекарственных препаратов относится к причинам гастрита?",options:["Антигистаминные препараты","НПВС","Бронходилататоры","Диуретики"],correctIndex:1,explanation:"Среди причин гастрита указан приём НПВС.",difficulty:"medium",tags:["гастрит","этиология"]},{id:"gastritis-ulcer-011",topicId:"gastritis-ulcer",question:"Какие факторы образа жизни входят в причины гастрита?",options:["Только избыточная физическая нагрузка","Только недостаток сна","Нерегулярное и раздражающее питание, алкоголь, курение, стресс","Только переохлаждение"],correctIndex:2,explanation:"К причинам гастрита относятся нерегулярное и раздражающее питание, алкоголь, курение и стресс.",difficulty:"medium",tags:["гастрит","этиология"]},{id:"gastritis-ulcer-012",topicId:"gastritis-ulcer",question:"Где локализуется боль при гастрите?",options:["В правом подреберье","В левом нижнем квадранте живота","В поясничной области","В эпигастрии"],correctIndex:3,explanation:"Основным проявлением гастрита является боль в эпигастрии.",difficulty:"medium",tags:["гастрит","симптомы"]},{id:"gastritis-ulcer-013",topicId:"gastritis-ulcer",question:"Какое ощущение после еды характерно для гастрита?",options:["Чувство тяжести","Чувство голода","Прилив сил","Онемение конечностей"],correctIndex:0,explanation:"Одним из основных симптомов гастрита является чувство тяжести после еды.",difficulty:"medium",tags:["гастрит","симптомы"]},{id:"gastritis-ulcer-014",topicId:"gastritis-ulcer",question:"Дефицит какого витамина относится к осложнениям гастрита?",options:["Витамина C","Витамина B₁₂","Витамина D","Витамина K"],correctIndex:1,explanation:"Среди осложнений гастрита указан дефицит витамина B₁₂ и анемия.",difficulty:"hard",tags:["гастрит","осложнения"]},{id:"gastritis-ulcer-015",topicId:"gastritis-ulcer",question:"Какое онкологическое осложнение может развиться при гастрите?",options:["Рак пищевода","Рак поджелудочной железы","Рак желудка","Колоректальный рак"],correctIndex:2,explanation:"К осложнениям гастрита относится рак желудка, которому предшествует кишечная метаплазия.",difficulty:"medium",tags:["гастрит","осложнения"]},{id:"gastritis-ulcer-016",topicId:"gastritis-ulcer",question:"Какие изменения слизистой относятся к осложнениям гастрита?",options:["Гипертрофия и полипоз только","Только полное восстановление слизистой","Только уплотнение мышечного слоя","Эрозии слизистой, её атрофия и кишечная метаплазия"],correctIndex:3,explanation:"К осложнениям гастрита относятся эрозии слизистой, атрофия слизистой и кишечная метаплазия.",difficulty:"medium",tags:["гастрит","осложнения"]},{id:"gastritis-ulcer-017",topicId:"gastritis-ulcer",question:"Какое опасное кровопотерей осложнение может развиться при гастрите?",options:["Желудочное кровотечение","Носовое кровотечение","Лёгочное кровотечение","Кишечное кровотечение из прямой кишки"],correctIndex:0,explanation:"Среди осложнений гастрита указано желудочное кровотечение.",difficulty:"medium",tags:["гастрит","осложнения"]},{id:"gastritis-ulcer-018",topicId:"gastritis-ulcer",question:"Какой основной эндоскопический метод применяется для диагностики гастрита?",options:["Колоноскопия","Гастроскопия с биопсией","Бронхоскопия","Цистоскопия"],correctIndex:1,explanation:"Диагностика гастрита проводится с помощью гастроскопии с биопсией.",difficulty:"medium",tags:["гастрит","диагностика"]},{id:"gastritis-ulcer-019",topicId:"gastritis-ulcer",question:"Какое исследование позволяет оценить кислотность желудка при гастрите?",options:["Копрограмма","УЗИ органов брюшной полости","pH-метрия","Общий анализ мочи"],correctIndex:2,explanation:"В диагностику гастрита входит pH-метрия наряду с гастроскопией, выявлением H. pylori и анализом крови.",difficulty:"medium",tags:["гастрит","диагностика"]},{id:"gastritis-ulcer-020",topicId:"gastritis-ulcer",question:"Что включает лечение гастрита?",options:["Только хирургическое вмешательство","Только приём антибиотиков","Только физиотерапию","Диету, ингибиторы протонной помпы, антациды, гастропротекторы и эрадикацию H. pylori"],correctIndex:3,explanation:"Лечение гастрита включает диету, ингибиторы протонной помпы, антациды, гастропротекторы и эрадикацию Helicobacter pylori при его наличии.",difficulty:"medium",tags:["гастрит","лечение"]},{id:"gastritis-ulcer-021",topicId:"gastritis-ulcer",question:"Воспаление какого отдела кишечника называется энтеритом?",options:["Тонкой кишки","Толстой кишки","Прямой кишки","Слепой кишки"],correctIndex:0,explanation:"Энтерит — воспаление тонкой кишки, чаще инфекционного происхождения.",difficulty:"easy",tags:["энтерит","терминология"]},{id:"gastritis-ulcer-022",topicId:"gastritis-ulcer",question:"Какое происхождение чаще имеет энтерит?",options:["Аутоиммунное","Инфекционное","Наследственное","Опухолевое"],correctIndex:1,explanation:"Энтерит чаще имеет инфекционное происхождение.",difficulty:"medium",tags:["энтерит","этиология"]},{id:"gastritis-ulcer-023",topicId:"gastritis-ulcer",question:"Воспаление толстой кишки носит название:",options:["Энтерит","Эзофагит","Колит","Гастрит"],correctIndex:2,explanation:"Колит — воспаление толстой кишки.",difficulty:"easy",tags:["колит","терминология"]},{id:"gastritis-ulcer-024",topicId:"gastritis-ulcer",question:"Чем вызывается колит?",options:["Только приёмом НПВС","Только кислотным рефлюксом","Исключительно паразитами","Инфекциями, аутоиммунными процессами или стрессом"],correctIndex:3,explanation:"Колит вызывается инфекциями, аутоиммунными процессами или стрессом.",difficulty:"medium",tags:["колит","этиология"]},{id:"gastritis-ulcer-025",topicId:"gastritis-ulcer",question:"Где локализуются боли при колите?",options:["В левом нижнем квадранте живота","В эпигастрии","В правом подреберье","За грудиной"],correctIndex:0,explanation:"Колит проявляется болями в левом нижнем квадранте живота, диареей с кровью или слизью и вздутием.",difficulty:"hard",tags:["колит","симптомы"]},{id:"gastritis-ulcer-026",topicId:"gastritis-ulcer",question:"Какой характер стула характерен для колита?",options:["Обесцвеченный жирный стул","Диарея с кровью или слизью","Полностью нормальный стул","Чёрный дёгтеобразный стул"],correctIndex:1,explanation:"Колит проявляется диареей с кровью или слизью.",difficulty:"medium",tags:["колит","симптомы"]},{id:"gastritis-ulcer-027",topicId:"gastritis-ulcer",question:"Что представляет собой гастроэнтероколит?",options:["Воспаление только желудка и пищевода","Воспаление только тонкой кишки","Одновременное воспаление желудка, тонкой и толстой кишки","Воспаление желчного пузыря и протоков"],correctIndex:2,explanation:"Гастроэнтероколит — одновременное воспаление желудка, тонкой и толстой кишки.",difficulty:"medium",tags:["гастроэнтероколит","терминология"]},{id:"gastritis-ulcer-028",topicId:"gastritis-ulcer",question:"При каких состояниях чаще всего возникает гастроэнтероколит?",options:["При аутоиммунных заболеваниях","При приёме НПВС","При наследственной предрасположенности","При пищевых отравлениях или вирусных инфекциях"],correctIndex:3,explanation:"Гастроэнтероколит чаще всего возникает при пищевых отравлениях или вирусных инфекциях.",difficulty:"medium",tags:["гастроэнтероколит","этиология"]},{id:"gastritis-ulcer-029",topicId:"gastritis-ulcer",question:"Что представляет собой язва желудка?",options:["Хроническое заболевание с образованием дефектов на слизистой из-за разъедания желудочным соком","Острое воспаление всей стенки желудка","Доброкачественное разрастание слизистой оболочки","Функциональное нарушение моторики желудка"],correctIndex:0,explanation:"Язва желудка — хроническое заболевание, характеризующееся образованием дефектов (язв) на слизистой оболочке из-за разъедания желудочным соком.",difficulty:"medium",tags:["язва","определение"]},{id:"gastritis-ulcer-030",topicId:"gastritis-ulcer",question:"Какие опасные состояния может вызвать язва желудка без должного лечения?",options:["Только анемию","Кровотечение, прободение стенки желудка и перитонит","Только изжогу и отрыжку","Только желчнокаменную болезнь"],correctIndex:1,explanation:"Без должного лечения язва может вызвать кровотечение, прободение (перфорацию) стенки желудка и перитонит.",difficulty:"medium",tags:["язва","осложнения"]},{id:"gastritis-ulcer-031",topicId:"gastritis-ulcer",question:"Каким термином обозначается прободение стенки желудка при язве?",options:["Метаплазия","Атрофия","Перфорация","Гипертрофия"],correctIndex:2,explanation:"Прободение стенки желудка при язве называется перфорацией.",difficulty:"medium",tags:["язва","терминология"]},{id:"gastritis-ulcer-032",topicId:"gastritis-ulcer",question:"Что назначают при выявленной инфекции Helicobacter pylori?",options:["Только диету","Только ферментные препараты","Только антациды","Комбинацию антибиотиков и ингибитора протонной помпы"],correctIndex:3,explanation:"Для эрадикации Helicobacter pylori обычно назначают комбинацию антибиотиков и ингибитора протонной помпы.",difficulty:"medium",tags:["лечение","эрадикация"]},{id:"gastritis-ulcer-033",topicId:"gastritis-ulcer",question:"Как называется процесс уничтожения инфекции Helicobacter pylori?",options:["Эрадикация","Санация","Регенерация","Резекция"],correctIndex:0,explanation:"Уничтожение инфекции Helicobacter pylori называется эрадикацией.",difficulty:"medium",tags:["лечение","терминология"]},{id:"gastritis-ulcer-034",topicId:"gastritis-ulcer",question:"Каково действие ингибиторов протонной помпы?",options:["Ускоряют опорожнение желудка","Уменьшают кислотность желудка и способствуют заживлению слизистой","Расщепляют пищу на усвояемые вещества","Уничтожают бактерии в кишечнике"],correctIndex:1,explanation:"Ингибиторы протонной помпы (ИПП) уменьшают кислотность желудка и способствуют заживлению слизистой.",difficulty:"medium",tags:["лечение","ИПП"]},{id:"gastritis-ulcer-035",topicId:"gastritis-ulcer",question:"Какую роль играют антациды и гастропротекторы?",options:["Уничтожают Helicobacter pylori","Восстанавливают кишечную микрофлору","Нейтрализуют кислоту и защищают слизистую","Замещают недостаток пищеварительных ферментов"],correctIndex:2,explanation:"Антациды и гастропротекторы нейтрализуют кислоту и защищают слизистую.",difficulty:"medium",tags:["лечение","антациды"]},{id:"gastritis-ulcer-036",topicId:"gastritis-ulcer",question:"Какое питание рекомендуется при гастрите и язвенной болезни?",options:["Обильные редкие приёмы пищи","Преимущественно острая и жареная пища","Только холодные блюда","Дробное питание с исключением острой, жареной, жирной пищи, алкоголя и кофеина"],correctIndex:3,explanation:"Диета включает дробное питание, исключение острой, жареной, жирной пищи, алкоголя и кофеина; предпочтение отдаётся тёплой и мягкой пище.",difficulty:"medium",tags:["лечение","диета"]},{id:"gastritis-ulcer-037",topicId:"gastritis-ulcer",question:"Какой пище отдаётся предпочтение в диете при гастрите?",options:["Тёплой и мягкой","Горячей и твёрдой","Холодной и жёсткой","Острой и пряной"],correctIndex:0,explanation:"В диете при гастрите предпочтение отдаётся тёплой и мягкой пище.",difficulty:"medium",tags:["лечение","диета"]},{id:"gastritis-ulcer-038",topicId:"gastritis-ulcer",question:"Что входит в коррекцию факторов риска при гастрите?",options:["Увеличение физической нагрузки до максимума","Отказ от алкоголя и курения, ограничение НПВС, снижение стресса","Полный отказ от любой пищи на несколько суток","Обязательный приём антибиотиков всем пациентам"],correctIndex:1,explanation:"Коррекция факторов риска включает отказ от алкоголя, курения, ограничение НПВС и снижение стресса.",difficulty:"medium",tags:["лечение","профилактика"]},{id:"gastritis-ulcer-039",topicId:"gastritis-ulcer",question:"Какое действующее вещество относится к ингибиторам протонной помпы?",options:["Панкреатин","Метоклопрамид","Омепразол","Лоперамид"],correctIndex:2,explanation:"Омепразол относится к ингибиторам протонной помпы наряду с пантопразолом, лансопразолом, эзомепразолом и рабепразолом.",difficulty:"medium",tags:["ИПП","препараты"]},{id:"gastritis-ulcer-040",topicId:"gastritis-ulcer",question:"Укажите ингибитор протонной помпы среди приведённых наименований.",options:["Симетикон","Гемицеллюлаза","Домперидон","Пантопразол"],correctIndex:3,explanation:"Пантопразол входит в группу ингибиторов протонной помпы.",difficulty:"medium",tags:["ИПП","препараты"]},{id:"gastritis-ulcer-041",topicId:"gastritis-ulcer",question:"Какое действующее вещество из группы ИПП является производным омепразола?",options:["Эзомепразол","Лансопразол","Рабепразол","Пантопразол"],correctIndex:0,explanation:"В таблице ИПП наряду с омепразолом указан эзомепразол.",difficulty:"hard",tags:["ИПП","препараты"]},{id:"gastritis-ulcer-042",topicId:"gastritis-ulcer",question:"Что представляют собой ферменты?",options:["Гормоны, регулирующие аппетит","Специальные белки, которые расщепляют пищу на усвояемые вещества","Углеводы, обеспечивающие организм энергией","Минеральные вещества слизистой желудка"],correctIndex:1,explanation:"Ферменты — это специальные белки, которые расщепляют пищу на усвояемые вещества.",difficulty:"medium",tags:["ферменты","определение"]},{id:"gastritis-ulcer-043",topicId:"gastritis-ulcer",question:"В каком случае назначают ферментные препараты?",options:["При избыточной кислотности желудка","При инфекции Helicobacter pylori","При недостаточности собственных ферментов, для нормализации пищеварения","При кишечных кровотечениях"],correctIndex:2,explanation:"При недостаточности ферментов назначают ферментные препараты для нормализации пищеварения.",difficulty:"medium",tags:["ферменты","показания"]},{id:"gastritis-ulcer-044",topicId:"gastritis-ulcer",question:"Какое действующее вещество является основой ферментных препаратов?",options:["Омепразол","Метоклопрамид","Лактулоза","Панкреатин"],correctIndex:3,explanation:"Основой ферментных препаратов является панкреатин, в том числе в комбинациях с желчными кислотами, симетиконом и гемицеллюлазой.",difficulty:"medium",tags:["ферменты","препараты"]},{id:"gastritis-ulcer-045",topicId:"gastritis-ulcer",question:"С какими веществами комбинируется панкреатин в ферментных препаратах?",options:["С желчными кислотами, симетиконом и гемицеллюлазой","С антибиотиками и ингибиторами протонной помпы","С витаминами группы B и железом","С пробиотиками и клетчаткой"],correctIndex:0,explanation:"В таблице ферментных препаратов приведены комбинации панкреатина с желчными кислотами, симетиконом и гемицеллюлазой.",difficulty:"hard",tags:["ферменты","препараты"]},{id:"gastritis-ulcer-046",topicId:"gastritis-ulcer",question:"Какое заболевание может стать осложнением гастрита и само по себе приводит к перитониту?",options:["Эзофагит","Язвенная болезнь","Дисбактериоз","Дивертикулит"],correctIndex:1,explanation:"Язвенная болезнь входит в число осложнений гастрита, а без лечения язва может привести к прободению стенки желудка и перитониту.",difficulty:"medium",tags:["гастрит","осложнения"]}];export{i as default};
